MoldCoatingBrushMaker.ironStock=12; MoldCoatingBrushMaker.bronzeStock=10; MoldCoatingBrushMaker.woodStock=14; MoldCoatingBrushMaker.leatherStock=12; MoldCoatingBrushMaker.silverStock=8; MoldCoatingBrushMaker.goldStock=6; MoldCoatingBrushMaker.jewelStock=4; MoldCoatingBrushMaker.pearlStock=4
